import { test, expect } from '@playwright/test';

test.describe('Login Password Mistyping - Error State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display clear failure message when password is invalid', async ({ page }) => {
    // Locate and fill username using getByLabel
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('tomsmith');

    // Locate and fill password using getByLabel
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify we are still on the login page
    const loginPageTitle = page.getByRole('heading', { name: /login/i });
    await expect(loginPageTitle).toBeVisible();

    // Verify flash banner is visible with error message
    const flashBanner = page.getByTestId('flash.error');
    await expect(flashBanner).toBeVisible();

    // Verify error message contains the expected text
    await expect(flashBanner).toContainText('Your password is invalid!');

    // Verify error message is visible and styled appropriately
    await expect(flashBanner).toHaveClass(/alert-danger/);
  });

  test('should not display error message when password is correct', async ({ page }) => {
    // Locate and fill username using getByLabel
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('tomsmith');

    // Locate and fill password using getByLabel
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('correctpassword');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify we are redirected to the dashboard
    const dashboardPageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardPageTitle).toBeVisible();

    // Verify error banner is not visible
    const flashBanner = page.getByTestId('flash.error');
    await expect(flashBanner).not.toBeVisible();

    // Verify success message is visible
    const successMessage = page.getByText(/successfully logged in/i);
    await expect(successMessage).toBeVisible();
  });
});
